# x <- "demye_WM"
lapply(c("demye_WM","demye_GM","demye_tot"),function(x){
  # define the column name
  col_id <- paste0(x,"_prop")
  
  # run the aggregation
  sobj_update@meta.data %>%
    group_by(original_sample_name,.data[[paste0(x,"_class")]]) %>%
    summarise(n = n(),
              !!col_id := mean(.data[[paste0(x,"_prop")]],na.rm = T)) %>%
    pivot_longer(names_to = "var",values_to = "prop",-c(original_sample_name,.data[[paste0(x,"_class")]],n)) %>%
    filter(!is.na(.data[[paste0(x,"_class")]])) %>%
    ggplot(aes(x = .data[[paste0(x,"_class")]],y=prop)) + geom_boxplot(outlier.shape = NA) + geom_point(position = position_jitter(width = 0.2,height = 0)) + 
    facet_wrap(~var,scales = "free") + theme_bw() + theme(strip.background = element_blank())
}) %>%
  wrap_plots()


# save the objects --------------------------------------------------------

# save the object
saveRDS(sobj_update,"../../out/object/analysis_R44/001_sobj_integrated_cleanup_manualAnnotation_updateDemyelination.rds")
